function upgradePrimaryNav(){
  const nav=document.querySelector(".bottom-nav");if(!nav)return;
  nav.classList.remove("afcl-six");nav.classList.add("product-five");
  const groupLink=nav.querySelector('[data-nav="groups"]');if(groupLink)groupLink.remove();
  const chapterLink=nav.querySelector('[data-nav="chapters"]');if(chapterLink){chapterLink.href="#/chapters";const label=chapterLink.querySelector("small");if(label)label.textContent="Chapters";chapterLink.setAttribute("aria-label","Chapters hub")}
  nav.querySelectorAll("a").forEach(a=>{const key=a.dataset.afclMain!=null?"afcl":a.dataset.nav;if(!key)return;const span=a.querySelector("span");if(span&&span.dataset.productIcon!==key){span.innerHTML=productIcon(key);span.dataset.productIcon=key;span.setAttribute("aria-hidden","true")}a.setAttribute("aria-current",a.classList.contains("active")?"page":"false")})
}
function syncPrimaryNavState(route){const nav=document.querySelector(".bottom-nav");if(!nav)return;const chapterRoutes=new Set(["groups","group","chapters","chapter"]);nav.querySelectorAll("a").forEach(a=>a.classList.remove("active"));let key=chapterRoutes.has(route)?"chapters":route;if(route==="rules"||route==="statistics"||route==="hall")key="more";if(route==="manager")key="individual";nav.querySelector(`[data-nav="${key}"]`)?.classList.add("active");nav.querySelectorAll("a").forEach(a=>a.setAttribute("aria-current",a.classList.contains("active")?"page":"false"))}
function upgradeChromeControls(){
  const s=document.getElementById("searchTrigger");if(s&&!s.dataset.productUi){s.innerHTML=`${productIcon("search")}<span>Search manager, team or chapter</span>`;s.dataset.productUi="1";s.setAttribute("aria-label","Search manager, team or chapter")}
  const r=document.getElementById("refreshBtn");if(r&&!r.dataset.productUi){r.innerHTML=productIcon("refresh");r.dataset.productUi="1";r.setAttribute("aria-label","Refresh rankings")}
  const gw=document.getElementById("gwSelect");gw?.setAttribute("aria-label","Select Gameweek");const gwWrap=gw?.closest(".gw-control");if(gwWrap&&!gwWrap.dataset.cleanGw){[...gwWrap.childNodes].forEach(n=>{if(n.nodeType===Node.TEXT_NODE&&n.textContent.trim())n.remove()});gwWrap.dataset.cleanGw="1"}
  document.getElementById("searchInput")?.setAttribute("aria-label","Search manager, team or chapter")
}
function classifyTables(root=document){root.querySelectorAll("table").forEach(t=>{t.querySelectorAll("th").forEach(th=>th.setAttribute("scope","col"));const h=[...t.querySelectorAll("thead th")].map(x=>x.textContent.trim().toLowerCase());if(t.classList.contains("afcl-table"))return;if(h.includes("chapter #"))t.dataset.tableKind="individual";else if(h.includes("team / manager")&&h.includes("move"))t.dataset.tableKind="ranking";else if(h[1]==="chapter"&&h.includes("move"))t.dataset.tableKind="group-summary"})}

function enhanceIndividualRanking(root){
  const filters=root.querySelector(".filters");if(filters)filters.classList.add("rank-filters");
  const table=root.querySelector(".rank-table");if(!table)return;
  if(!table.dataset.rankCompact){
    const headRow=table.querySelector("thead tr");if(headRow?.children?.[3])headRow.children[3].remove();
    table.querySelectorAll("tbody tr").forEach(tr=>{if(tr.children?.[3])tr.children[3].remove()});
    table.dataset.rankCompact="1";
  }
  table.dataset.tableKind="individual-compact";
  table.classList.add("compact");
  table.setAttribute("aria-label","Individual Ranking");
  table.closest(".section")?.classList.add("individual-compact-section");
}

function markKpis(root){root.querySelectorAll(".kpi").forEach(k=>{const label=k.querySelector("span")?.textContent.trim().toLowerCase()||"",primary=label==="overall leader"||label==="gw leader"||label==="highest gw"||(label.includes("gameweek")&&label.includes("leader"));k.classList.toggle("is-primary",primary);k.classList.toggle("is-secondary",!primary)})}
let homeSnapshotPromise=null;
function loadHomeSnapshot(){if(homeSnapshotPromise)return homeSnapshotPromise;homeSnapshotPromise=(async()=>{const manifest=await json("data/manifest.json");return json(manifest.snapshot)})().catch(e=>{homeSnapshotPromise=null;throw e});return homeSnapshotPromise}
function homeLeaderFromSnapshot(data,gw){const rows=(data.individual||[]).map(base=>{const hs=(data.histories?.[base.id]||[]).map(Number),score=Number(hs[gw-1]||0),total=hs.slice(0,gw).reduce((a,b)=>a+b,0);return{...base,score,total}}).sort((a,b)=>b.total-a.total||String(a.team_name||"").localeCompare(String(b.team_name||"")));return [...rows].sort((a,b)=>b.score-a.score)[0]||null}
function homeEsc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\'":"&#39;","\"":"&quot;"}[c]))}
function homeKpi(card,{label,value,unit="",team="",manager="",chapter="",note=""}={}){if(!card)return;card.classList.add("home-summary-kpi");const identity=(team||manager||chapter)?`<div class="home-kpi-identity">${team?`<b>${homeEsc(team)}</b>`:""}${manager?`<small>${homeEsc(manager)}</small>`:""}${chapter?`<small>${homeEsc(chapter)}</small>`:""}</div>`:"";card.innerHTML=`<span class="home-kpi-label">${homeEsc(label||"")}</span><div class="home-kpi-score"><strong>${homeEsc(value??"—")}</strong>${unit?`<em>${homeEsc(unit)}</em>`:""}</div>${identity}${note?`<small class="home-kpi-note">${homeEsc(note)}</small>`:""}`}
function homeCompactOverallTable(section){
  if(!section)return;
  const table=section.querySelector("table");if(!table)return;
  table.classList.add("compact");
  table.dataset.tableKind="home-overall";
  table.setAttribute("aria-label","Overall Top 5");
}
function homeGwMetrics(data,gw){
  const rows=(data.individual||[]).map(base=>{
    const hs=(data.histories?.[base.id]||[]).map(Number);
    return {...base,score:Number(hs[gw-1]||0),total:hs.slice(0,gw).reduce((a,b)=>a+b,0)}
  });
  const scores=rows.map(r=>r.score);
  const average=scores.length?scores.reduce((a,b)=>a+b,0)/scores.length:0;
  const below=scores.filter(x=>x<average).length;
  const leader=[...rows].sort((a,b)=>b.score-a.score||b.total-a.total||String(a.team_name||"").localeCompare(String(b.team_name||"")))[0]||null;
  return {leader,average,below,count:scores.length}
}
async function enhanceHomeVisuals(root){
  const gw=Number(document.getElementById("gwSelect")?.value||0);
  const hero=root.querySelector(":scope > .hero");if(hero&&!hero.classList.contains("afcl-product-hero")){hero.classList.add("home-product-hero");const h1=hero.querySelector("h1"),eyebrow=hero.querySelector(".eyebrow"),p=hero.querySelector("p");if(h1)h1.textContent=gw?`GW${gw} Overview`:"Competition Overview";if(eyebrow)eyebrow.textContent=gw?`GAMEWEEK ${gw}`:"CURRENT GAMEWEEK";if(p)p.textContent="Leaders and Group Competition at a glance.";hero.querySelector(".hero-meta")?.remove()}
  const sections=[...root.querySelectorAll(".section")];
  const overall=sections.find(x=>x.querySelector(".section-head h2")?.textContent.trim()==="Overall Top 10"||x.querySelector(".section-head h2")?.textContent.trim()==="Overall Top 5");
  const group=sections.find(x=>x.querySelector(".section-head h2")?.textContent.trim()==="Group Top 5");
  const mover=sections.find(x=>x.querySelector(".section-head h2")?.textContent.trim()==="Biggest Climbers");if(mover)mover.remove();
  if(overall){
    const h=overall.querySelector(".section-head h2");if(h)h.textContent="Overall Top 5";
    [...overall.querySelectorAll("tbody tr")].slice(5).forEach(x=>x.remove())
  }
  const cards=[...root.querySelectorAll(":scope > .kpis > .kpi")];
  const firstOverall=overall?.querySelector("tbody tr");
  const team=firstOverall?.querySelector(".team-link")?.textContent.trim()||cards[0]?.querySelector("small")?.textContent.trim()||"—";
  const manager=firstOverall?.querySelector(".subline")?.textContent.trim()||"";
  const chapter=firstOverall?.querySelector(".chapter-link")?.textContent.trim()||"";
  const scores=firstOverall?[...firstOverall.querySelectorAll("td.score")].map(x=>x.textContent.trim()):[];
  const overallTotal=scores.at(-1)||cards[0]?.querySelector("strong")?.textContent.trim()||"—";
  homeKpi(cards[0],{label:"Overall Leader",value:overallTotal,unit:"Total Score",team,manager,chapter});
  homeCompactOverallTable(overall);

  const groupFirst=group?.querySelector("tbody tr");
  const groupChapter=groupFirst?.querySelector(".chapter-link")?.textContent.trim()||cards[2]?.querySelector("small")?.textContent.trim()||"—";
  const groupScores=groupFirst?[...groupFirst.querySelectorAll("td.score")].map(x=>x.textContent.trim()):[];
  const groupTotal=groupScores.at(-1)||cards[2]?.querySelector("strong")?.textContent.trim()||"—";
  homeKpi(cards[2],{label:"Leading Group",value:groupTotal,unit:"Cumulative Score",team:groupChapter});

  try{
    const data=await loadHomeSnapshot();
    const activeGw=gw||Number(data.meta?.gw||1);
    const metrics=homeGwMetrics(data,activeGw);
    if(document.body.dataset.route==="home"){
      if(metrics.leader)homeKpi(cards[1],{label:`Gameweek ${activeGw} Leader`,value:metrics.leader.score,unit:"Gameweek Score",team:metrics.leader.team_name,manager:metrics.leader.manager_name,chapter:metrics.leader.chapter});
      const rounded=Math.round(metrics.average*10)/10;
      const avgText=Number.isInteger(rounded)?String(rounded):rounded.toFixed(1);
      const belowText=`${metrics.below.toLocaleString("en-MY")} ${metrics.below===1?"manager":"managers"} below average`;
      homeKpi(cards[3],{label:`Gameweek ${activeGw} Average`,value:avgText,unit:"Score",note:belowText})
    }
  }catch(e){
    const oldLeader=cards[1];
    if(oldLeader){
      const score=oldLeader.querySelector("strong")?.textContent.trim()||"—";
      const name=oldLeader.querySelector("small")?.textContent.trim()||"—";
      homeKpi(oldLeader,{label:gw?`Gameweek ${gw} Leader`:"Gameweek Leader",value:score,unit:"Gameweek Score",team:name})
    }
    const oldAvg=cards[3];
    if(oldAvg){
      const score=oldAvg.querySelector("strong")?.textContent.trim()||"—";
      homeKpi(oldAvg,{label:gw?`Gameweek ${gw} Average`:"Gameweek Average",value:score,unit:"Score"})
    }
  }
  markKpis(root)
}
function moreCardIcon(card,key){const span=card.querySelector("span");if(span){span.innerHTML=productIcon(key);span.setAttribute("aria-hidden","true")}}
function enhanceMoreVisuals(root){const grid=root.querySelector(".more-grid");if(!grid)return;[...grid.querySelectorAll(".more-card")].forEach(c=>{const t=c.textContent.trim().toLowerCase();if(t==="all chapters"||t==="full ranking")c.remove()});root.querySelector(".notice")?.remove();grid.querySelector(".more-subhead")?.remove();const cards=[...grid.querySelectorAll(".more-card")];const byText=new Map(cards.map(c=>[c.textContent.trim().toLowerCase(),c]));[["statistics","stats"],["hall of fame","hall"],["rules & faq","rules"]].forEach(([name,key])=>{const c=byText.get(name);if(!c)return;grid.appendChild(c);c.classList.remove("secondary-tool");c.classList.add("primary-tool");moreCardIcon(c,key)})}

function statEligibleFrom(manager){const n=Number(manager?.eligible_from||1);return Number.isFinite(n)&&n>0?n:1}
function computeSeasonStatistics(data,gw){
  const managers=(data.individual||[]), histories=data.histories||{}, records=[];
  const byId=new Map(managers.map(m=>[String(m.id),m]));
  for(const m of managers){
    const hs=(histories[m.id]||[]).map(Number), start=statEligibleFrom(m);
    for(let g=start;g<=gw;g++){
      if(g<1||g>hs.length)continue;
      records.push({...m,recordGw:g,recordScore:Number(hs[g-1]||0)});
    }
  }
  const desc=(a,b)=>b-a, asc=(a,b)=>a-b;
  const high=records.length?[...records].sort((a,b)=>desc(a.recordScore,b.recordScore)||a.recordGw-b.recordGw||String(a.team_name||"").localeCompare(String(b.team_name||"")))[0]:null;
  const low=records.length?[...records].sort((a,b)=>asc(a.recordScore,b.recordScore)||a.recordGw-b.recordGw||String(a.team_name||"").localeCompare(String(b.team_name||"")))[0]:null;
  const gwAverages=[];
  for(let g=1;g<=gw;g++){
    const vals=managers.filter(m=>statEligibleFrom(m)<=g).map(m=>Number((histories[m.id]||[])[g-1]||0));
    if(vals.length)gwAverages.push({gw:g,value:vals.reduce((a,b)=>a+b,0)/vals.length});
  }
  const highAvg=gwAverages.length?[...gwAverages].sort((a,b)=>b.value-a.value||a.gw-b.gw)[0]:null;
  const eligibleChapters=new Set((data.chapters||[]).filter(c=>c.group_eligible).map(c=>c.chapter));
  const groupRecords=[];
  for(const chapter of eligibleChapters){
    const members=managers.filter(m=>m.chapter===chapter);
    for(let g=1;g<=gw;g++){
      const vals=members.filter(m=>statEligibleFrom(m)<=g).map(m=>Number((histories[m.id]||[])[g-1]||0)).sort((a,b)=>b-a).slice(0,5);
      if(vals.length>=5)groupRecords.push({chapter,gw:g,score:vals.reduce((a,b)=>a+b,0)});
    }
  }
  const groupHigh=groupRecords.length?[...groupRecords].sort((a,b)=>b.score-a.score||a.gw-b.gw||String(a.chapter).localeCompare(String(b.chapter)))[0]:null;
  const hundredCount=records.filter(r=>r.recordScore>=100).length;
  const perManager=managers.map(m=>{
    const hs=(histories[m.id]||[]).map(Number), start=statEligibleFrom(m), vals=[];
    for(let g=start;g<=gw;g++)if(g<=hs.length)vals.push({gw:g,score:Number(hs[g-1]||0)});
    const average=vals.length?vals.reduce((n,x)=>n+x.score,0)/vals.length:null;
    const hundred=vals.filter(x=>x.score>=100).length, sub50=vals.filter(x=>x.score<50).length;
    let improvement=null,drop=null;
    for(let i=1;i<vals.length;i++){
      const d=vals[i].score-vals[i-1].score, item={...m,delta:d,fromGw:vals[i-1].gw,toGw:vals[i].gw};
      if(!improvement||d>improvement.delta)improvement=item;
      if(!drop||d<drop.delta)drop=item;
    }
    return {...m,average,hundred,sub50,improvement,drop};
  }).filter(m=>m.average!=null);
  const mostHundred=perManager.length?[...perManager].sort((a,b)=>b.hundred-a.hundred||(b.average??0)-(a.average??0))[0]:null;
  const mostSub50=perManager.length?[...perManager].sort((a,b)=>b.sub50-a.sub50||(a.average??Infinity)-(b.average??Infinity))[0]:null;
  const lowestAverage=perManager.length?[...perManager].sort((a,b)=>(a.average??Infinity)-(b.average??Infinity)||String(a.team_name||"").localeCompare(String(b.team_name||"")))[0]:null;
  const improvements=perManager.map(x=>x.improvement).filter(Boolean),drops=perManager.map(x=>x.drop).filter(Boolean);
  const improvement=improvements.length?[...improvements].sort((a,b)=>b.delta-a.delta)[0]:null;
  const drop=drops.length?[...drops].sort((a,b)=>a.delta-b.delta)[0]:null;
  return {high,low,highAvg,groupHigh,hundredCount,mostHundred,mostSub50,lowestAverage,improvement,drop,byId};
}
