function ensureAfclNav(){ensureAfclStyle();ensureAfclPremiumStyle();const nav=document.querySelector(".bottom-nav");if(!nav)return;nav.classList.remove("afcl-six");nav.classList.add("product-five");let a=nav.querySelector("[data-afcl-main]");if(!a){a=document.createElement("a");a.href=ah("overview");a.dataset.afclMain="1";a.dataset.nav="afcl";a.setAttribute("aria-label","ANSARA Fantasy Champions League");a.innerHTML='<span aria-hidden="true"></span><small>AFCL</small>';const more=nav.querySelector('[data-nav="more"]');nav.insertBefore(a,more||null)}else{a.href=ah("overview");a.dataset.nav="afcl"}const active=!!afclRoute();if(active){nav.querySelectorAll("a").forEach(x=>x.classList.remove("active"));a.classList.add("active")}else a.classList.remove("active");upgradePrimaryNav()}
function ensureRulesNav(){ensureAfclNav();const nav=document.querySelector(".bottom-nav");if(!nav)return;nav.querySelectorAll("a").forEach(x=>x.classList.remove("active"));nav.querySelector('[data-nav="more"]')?.classList.add("active")}

async function loadAfcl(){if(A.data)return A;if(A.loading)return A.loading;A.loading=(async()=>{A.manifest=await json("data/manifest.json");A.data=await json(A.manifest.snapshot);buildSeeding();if(isFinal())A.draw=buildOfficialDraw();return A})().catch(e=>{A.loading=null;throw e});return A.loading}
function buildSeeding(){const q=AFCL.qualificationGw;const rows=(A.data.individual||[]).map(base=>{const hs=(A.data.histories?.[base.id]||[]).map(Number),gw2=Number(hs[q-1]||0),total=hs.slice(0,q).reduce((s,x)=>s+x,0);return {...base,gw2,total,tie:hashString(`${AFCL.tieSeed}|${base.id}`)}}).sort((a,b)=>b.gw2-a.gw2||b.total-a.total||a.tie-b.tie||String(a.team_name||"").localeCompare(String(b.team_name||"")));rows.forEach((r,i)=>{r.seed=i+1;r.qualified=i<AFCL.qualifiers;r.pot=r.qualified?Math.floor(i/AFCL.potSize)+1:null});A.seeding=rows;A.seedMap=new Map(rows.map(r=>[String(r.id),r]))}
function candidateDraw(attempt){const groups=GROUP_LABELS.map(label=>({label,members:[],potCounts:[0,0,0,0,0],chapterCounts:new Map()})),rng=mulberry32(hashString(`${AFCL.drawSeed}|${attempt}`));for(let pot=1;pot<=4;pot++){const teams=A.seeding.filter(x=>x.qualified&&x.pot===pot),freq=new Map();teams.forEach(t=>freq.set(t.chapter,(freq.get(t.chapter)||0)+1));const ordered=shuffled(teams,rng).sort((a,b)=>(freq.get(b.chapter)||0)-(freq.get(a.chapter)||0));for(const team of ordered){let best=null,score=Infinity;for(const g of groups){if(g.potCounts[pot]>=6)continue;const same=g.chapterCounts.get(team.chapter)||0,s=same*100000+g.potCounts[pot]*1000+g.members.length*10+rng();if(s<score){score=s;best=g}}if(!best)throw new Error("AFCL draw capacity error");best.members.push(team);best.potCounts[pot]++;best.chapterCounts.set(team.chapter,(best.chapterCounts.get(team.chapter)||0)+1)}}let collisions=0,maxSame=0;for(const g of groups)for(const c of g.chapterCounts.values()){if(c>1)collisions+=c-1;maxSame=Math.max(maxSame,c)}return{groups,collisions,maxSame,attempt}}
function buildOfficialDraw(){let best=null;for(let a=0;a<120;a++){const c=candidateDraw(a);if(!best||c.collisions<best.collisions||(c.collisions===best.collisions&&c.maxSame<best.maxSame))best=c;if(best.collisions===0)break}const reveal=[];for(let pot=1;pot<=4;pot++){const teams=A.seeding.filter(x=>x.qualified&&x.pot===pot),order=shuffled(teams,mulberry32(hashString(`${AFCL.drawSeed}|REVEAL|P${pot}`))),map=new Map();best.groups.forEach(g=>g.members.filter(x=>x.pot===pot).forEach(x=>map.set(String(x.id),g.label)));order.forEach(t=>reveal.push({...t,group:map.get(String(t.id))}))}const byId=new Map();best.groups.forEach(g=>g.members.forEach(x=>byId.set(String(x.id),g.label)));return{...best,reveal,byId}}
function fixtureRoundsForGroup(group){const teams=[...group.members].sort((a,b)=>a.seed-b.seed),n=teams.length;if(n!==24)return[];const list=[...teams],rounds=[];for(let r=0;r<n-1;r++){const matches=[];for(let i=0;i<n/2;i++){let home=list[i],away=list[n-1-i];if((r+i)%2===1)[home,away]=[away,home];matches.push({home,away})}rounds.push(matches);const fixed=list[0],rest=list.slice(1);rest.unshift(rest.pop());list.splice(0,list.length,fixed,...rest)}return rounds}
function groupStandings(group,throughGw=currentGw()){const rounds=fixtureRoundsForGroup(group),start=AFCL.groupStartGw,end=Math.min(throughGw,AFCL.groupEndGw),stats=new Map(group.members.map(t=>[String(t.id),{...t,p:0,w:0,d:0,l:0,pf:0,pa:0,gd:0,pts:0,h2h:new Map()}]));if(end<start)return[...stats.values()].sort((a,b)=>a.seed-b.seed);for(let gw=start;gw<=end;gw++){const round=rounds[gw-start];if(!round)continue;for(const m of round){const hs=Number((A.data.histories?.[m.home.id]||[])[gw-1]||0),as=Number((A.data.histories?.[m.away.id]||[])[gw-1]||0),h=stats.get(String(m.home.id)),a=stats.get(String(m.away.id));h.p++;a.p++;h.pf+=hs;h.pa+=as;a.pf+=as;a.pa+=hs;if(hs>as){h.w++;a.l++;h.pts+=3;h.h2h.set(String(a.id),3);a.h2h.set(String(h.id),0)}else if(hs<as){a.w++;h.l++;a.pts+=3;a.h2h.set(String(h.id),3);h.h2h.set(String(a.id),0)}else{h.d++;a.d++;h.pts++;a.pts++;h.h2h.set(String(a.id),1);a.h2h.set(String(h.id),1)}}}const rows=[...stats.values()];rows.forEach(x=>x.gd=x.pf-x.pa);const byPts=new Map();rows.forEach(x=>{if(!byPts.has(x.pts))byPts.set(x.pts,[]);byPts.get(x.pts).push(x)});const out=[];[...byPts.keys()].sort((a,b)=>b-a).forEach(pts=>{const tied=byPts.get(pts);tied.forEach(x=>x.mini=tied.reduce((s,y)=>s+(x.id===y.id?0:(x.h2h.get(String(y.id))||0)),0));tied.sort((a,b)=>b.mini-a.mini||b.pf-a.pf||b.gd-a.gd||a.seed-b.seed);out.push(...tied)});out.forEach((x,i)=>x.pos=i+1);return out}

function tabs(active){return `<nav class="afcl-tabs" aria-label="AFCL sections">${[["overview","Overview"],["qualification","Qualification"],["pots","Pots"],["draw","Live Draw"],["groups","Groups"],["knockout","Knockout"]].map(([r,l])=>`<a href="${ah(r)}" class="${active===r?"active":""}" ${active===r?'aria-current="page"':""}>${l}</a>`).join("")}</nav>`}
function pageHead(title,sub=""){return `<div class="page-head"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:""}</div></div>`}
function notice(){return isFinal()?'<div class="afcl-alert final"><strong>Qualification locked.</strong> Official GW2 scores now determine the Top 768, seeding and pots.</div>':'<div class="afcl-alert"><strong>Provisional qualification.</strong> Seeds and pots can still change until FPL finalises GW2.</div>'}
function hero(){return `<section class="afcl-masthead"><div class="afcl-masthead-copy"><div class="afcl-kicker">AFCL · ${AFCL.season}</div><h1>ANSARA Fantasy Champions League</h1></div><div class="afcl-masthead-mark"><img class="afcl-logo" src="${AFCL_LOGO_DATA}" alt="ANSARA Fantasy Champions League ${AFCL.season}"></div></section>`}
function seedTable(rows,cut=true){return `<div class="afcl-table-wrap"><table class="afcl-table afcl-seed-table"><caption class="sr-only">AFCL qualification and seeding</caption><thead><tr><th scope="col">#</th><th scope="col">Team / Manager</th><th scope="col">Chapter</th><th scope="col">GW2</th><th scope="col">Total</th><th scope="col">Pot</th></tr></thead><tbody>${rows.map(r=>{const cls=[r.seed<=5?"afcl-top-seed":"",cut&&r.seed===768?"afcl-cut-in":"",cut&&r.seed===769?"afcl-cut-out":""].filter(Boolean).join(" ");return `<tr class="${cls}"><td class="afcl-rank">${r.seed}</td><td><a class="afcl-team" href="#/manager/${enc(r.id)}">${esc(r.team_name)}</a><span class="afcl-sub">${esc(r.manager_name)}</span></td><td>${esc(r.chapter)}</td><td><strong>${nfmt(r.gw2)}</strong></td><td>${nfmt(r.total)}</td><td>${r.pot?`<span class="afcl-badge p${r.pot}">P${r.pot}</span>`:"—"}</td></tr>`}).join("")}</tbody></table></div>`}

function knockoutStageState(gw=currentGw()){
  const stages=[{from:26,to:27,short:"R128",name:"Round of 128",teams:128},{from:28,to:29,short:"R64",name:"Round of 64",teams:64},{from:30,to:31,short:"R32",name:"Round of 32",teams:32},{from:32,to:33,short:"R16",name:"Round of 16",teams:16},{from:34,to:35,short:"QF",name:"Quarter Final",teams:8},{from:36,to:37,short:"SF",name:"Semi Final",teams:4},{from:38,to:38,short:"FINAL",name:"Grand Final",teams:2}];
  const x=stages.find(r=>gw>=r.from&&gw<=r.to)||null;if(!x)return null;return {...x,leg:x.from===x.to?1:gw-x.from+1,legs:x.from===x.to?1:2};
}
function afclCurrentStage(){
  const gw=currentGw();
  if(!isFinal())return{title:"Qualification in Progress",detail:"GW2 qualification and seeding remain provisional.",action:ah("qualification"),actionLabel:"View Qualification"};
  if(!drawComplete())return{title:"Qualification Complete",detail:"Top 768 confirmed from GW2.",next:"Next: Official Live Draw",action:ah("draw"),actionLabel:"Live Draw"};
  if(gw<AFCL.groupStartGw)return{title:"Official Draw Complete",detail:"All 32 groups are confirmed.",next:"Next: Group Stage · GW3",action:ah("groups"),actionLabel:"View Groups"};
  if(gw<=AFCL.groupEndGw)return{title:`Group Stage · GW${gw}`,detail:`Round ${gw-AFCL.groupStartGw+1} of 23`,action:ah("groups"),actionLabel:"View Groups"};
  const ko=knockoutStageState(gw);if(ko)return{title:`Knockout Stage · ${ko.name}`,detail:ko.legs===1?`GW${gw}`:`Leg ${ko.leg} of ${ko.legs} · GW${gw}`,action:ah("knockout"),actionLabel:"View Knockout"};
  return{title:"Season Complete",detail:"AFCL 2026/27 has concluded."};
}

function overviewPage(){const st=afclCurrentStage();return `${hero()}<section class="afcl-current-stage"><span class="afcl-state-label">Current Stage</span><h2>${esc(st.title)}</h2><p>${esc(st.detail)}</p>${st.next?`<strong class="afcl-state-next">${esc(st.next)}</strong>`:""}${st.action?`<a class="afcl-state-link" href="${st.action}">${esc(st.actionLabel)}</a>`:""}</section>`}
function qualificationPage(){const q=A.search.trim().toLowerCase();let rows=A.seeding;if(A.filter==="Q")rows=rows.filter(x=>x.qualified);if(A.filter==="OUT")rows=rows.filter(x=>!x.qualified);if(q)rows=rows.filter(x=>`${x.team_name} ${x.manager_name} ${x.chapter}`.toLowerCase().includes(q));const visible=rows.slice(0,A.qualLimit),remaining=Math.max(0,rows.length-visible.length);return `${pageHead("Qualification & Seeding","Official GW2 ranking · Top 768 qualify")}<div class="afcl-search afcl-qualification-search"><input id="afclQualSearch" value="${esc(A.search)}" placeholder="Search team, manager or chapter" aria-label="Search AFCL qualification"><select id="afclQualFilter" aria-label="Filter AFCL qualification"><option value="ALL">All</option><option value="Q" ${A.filter==="Q"?"selected":""}>Qualified</option><option value="OUT" ${A.filter==="OUT"?"selected":""}>Eliminated</option></select></div><section class="afcl-card afcl-qualification-list">${seedTable(visible,true)}${remaining?`<div class="afcl-load-more"><button id="afclQualMore" class="afcl-btn light" type="button">Show ${Math.min(120,remaining)} more</button></div>`:""}</section>`}
function potsPage(){const p=Math.min(4,Math.max(1,Number(A.selectedPot||1))),query=A.potSearch.trim().toLowerCase();let rows=A.seeding.filter(x=>x.pot===p);if(query)rows=rows.filter(x=>`${x.team_name} ${x.manager_name} ${x.chapter}`.toLowerCase().includes(query));const all=A.seeding.filter(x=>x.pot===p);return `${pageHead("Seeding Pots","4 pots • 192 teams per pot")}<div class="pot-selector">${[1,2,3,4].map(x=>`<button type="button" data-afcl-pot="${x}" class="${p===x?"active":""}">Pot ${x}<span class="sr-only"> seeds ${A.seeding.find(r=>r.pot===x)?.seed} to ${[...A.seeding].reverse().find(r=>r.pot===x)?.seed}</span></button>`).join("")}</div><div class="afcl-search"><input id="afclPotSearch" value="${esc(A.potSearch)}" placeholder="Search Pot ${p}" aria-label="Search Pot ${p}"><div class="afcl-result-meta" style="margin:0;justify-content:flex-end"><span>${rows.length} / ${all.length}</span></div></div><article class="pot-card"><div class="pot-head"><strong>POT ${p}</strong><span>Seeds ${all[0]?.seed}–${all.at(-1)?.seed}</span></div><div class="pot-list">${rows.map(r=>`<div class="pot-row"><div class="seed">#${r.seed}</div><div><strong>${esc(r.team_name)}</strong><small>${esc(r.manager_name)} • ${esc(r.chapter)}</small></div><div>${nfmt(r.gw2)}</div></div>`).join("")||'<div class="afcl-empty">No matching teams in this pot.</div>'}</div></article>`}
async function hostDigest(v){const b=new TextEncoder().encode(v),h=await crypto.subtle.digest("SHA-256",b);return[...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function unlockHost(){if(!A.hostMode)return;const code=prompt("Enter AFCL host code");if(!code)return;if(await hostDigest(code.trim())===AFCL_HOST_HASH){A.hostAuthorized=true;sessionStorage.setItem("afcl-host-ok","1");renderAfcl(["draw"])}else alert("Invalid AFCL host code.")}
async function writeLive(patch){if(!A.hostAuthorized)throw new Error("Host control unavailable");const next={...A.live,...patch,updated_at:new Date().toISOString()};A.live=next;await update(afclLiveRef,next)}
function drawPage(){if(!isFinal())return `${pageHead("AFCL Live Draw","Available after GW2 is final")}<section class="afcl-state-panel"><h2>Live Draw not available yet</h2><p>Qualification and seeding must be final before the official draw can begin.</p></section>`;const status=A.live.status||"pending";if(A.hostMode&&!A.hostAuthorized)return `${pageHead("AFCL Live Draw","Host control")}<section class="afcl-state-panel"><h2>Official Live Draw</h2><p>Unlock the authorised host console to control the official draw.</p><button id="afclHostUnlock" class="afcl-primary afcl-compact-action" type="button">Unlock Host Console</button></section>`;if(status==="pending"&&!A.hostAuthorized)return `${pageHead("AFCL Live Draw","Draw schedule · To be announced")}<section class="afcl-state-panel"><h2>Official Live Draw</h2><p>Draw has not started.</p></section>`;if(status==="pending"&&A.hostAuthorized)return `${pageHead("AFCL Live Draw","Host control")}<section class="afcl-state-panel"><h2>Official Live Draw</h2><p>The official draw is ready to begin.</p><button id="afclDrawStart" class="afcl-primary afcl-compact-action" type="button">Start Official Live Draw</button></section>`;return liveDrawStage()}
function liveDrawStage(){const total=A.draw.reveal.length,idx=Math.min(Number(A.live.index||0),total),pct=(idx/total*100).toFixed(1),current=idx?A.draw.reveal[idx-1]:null,next=A.draw.reveal[idx]||null,done=idx>=total||A.live.status==="complete",running=A.live.status==="running",paused=A.live.status==="paused";const reveal=current?`<div><div class="pot">POT ${current.pot} • SEED #${current.seed}</div><h2>${esc(current.team_name)}</h2><p>${esc(current.manager_name)}</p><p>${esc(current.chapter)}</p><div class="destination">GROUP <b>${esc(current.group)}</b></div></div>`:`<div><div class="pot">AFCL OFFICIAL DRAW</div><h2>768 teams. 32 groups.</h2><p>${A.hostAuthorized?"Press Start once. The draw reveals every team automatically.":"Waiting for the first reveal."}</p></div>`;const controls=A.hostAuthorized?`<div class="draw-controls"><button id="afclDrawStart" ${done||running?"disabled":""}>${idx?"Resume Draw":"Start Live Draw"}</button><button id="afclDrawPause" class="secondary" ${!running||done?"disabled":""}>Pause</button><select id="afclDrawSpeed"><option value="1" ${A.drawSpeed===1?"selected":""}>1× • 3 sec</option><option value="1.5" ${A.drawSpeed===1.5?"selected":""}>1.5×</option><option value="2" ${A.drawSpeed===2?"selected":""}>2×</option></select></div>`:"";return `${pageHead("AFCL Live Draw",done?"Official draw complete":paused?"Official draw paused":running?"LIVE • synced for all viewers":"Official draw console")}<section class="draw-stage"><div class="draw-progress"><strong>${done?"DRAW COMPLETE":`Draw ${idx} / ${total}`}</strong><span>${done?"All groups complete":next?`Next: Pot ${next.pot}`:"Ready"}</span></div><div class="draw-bar"><i style="width:${pct}%"></i></div><div class="draw-reveal">${reveal}</div>${controls}<div class="draw-note">${A.hostAuthorized?"Host controls update the shared live position.":"Live progress is controlled by the AFCL host."} Refresh returns to the current official position.</div></section>${drawBoard(idx)}`}
function drawBoard(idx){const shown=new Map(GROUP_LABELS.map(g=>[g,[]]));A.draw.reveal.slice(0,idx).forEach(x=>shown.get(x.group).push(x));const latest=A.draw.reveal[Math.max(0,idx-1)]||null,selected=A.drawBoardGroup||latest?.group||"A",rows=shown.get(selected)||[];return `<section class="afcl-card"><div class="afcl-card-head"><div><h2>Live Group Board</h2><p>${idx} of 768 teams revealed</p></div></div><div class="draw-board-tools"><span class="subline">Jump to a group</span><select id="afclDrawGroupSelect" aria-label="Select Live Draw group">${GROUP_LABELS.map(g=>`<option value="${g}" ${selected===g?"selected":""}>Group ${g} • ${shown.get(g).length}/24</option>`).join("")}</select></div><div class="draw-group-chips">${GROUP_LABELS.map(g=>`<button type="button" data-afcl-draw-group="${g}" class="draw-group-chip ${selected===g?"active":""}"><b>${g}</b>${shown.get(g).length}/24</button>`).join("")}</div><div class="afcl-group-grid single"><article class="afcl-group-card"><div class="afcl-group-head"><strong>GROUP ${selected}</strong><span>${rows.length}/24</span></div><div class="afcl-group-list">${rows.length?rows.map((r,i)=>`<div class="afcl-group-row"><div class="slot">${i+1}</div><div><strong>${esc(r.team_name)}</strong><small>${esc(r.manager_name)} • ${esc(r.chapter)}</small></div><div>P${r.pot}</div></div>`).join(""):'<div class="afcl-empty">Awaiting draw</div>'}</div></article></div></section>`}
function bindDraw(){document.getElementById("afclHostUnlock")?.addEventListener("click",unlockHost);document.getElementById("afclDrawStart")?.addEventListener("click",async()=>{if(!A.hostAuthorized)return;A.drawPaused=false;A.drawRunning=true;A.drawIndex=Number(A.live.index||0);await writeLive({status:"running",index:A.drawIndex,speed:A.drawSpeed});runDraw()});document.getElementById("afclDrawPause")?.addEventListener("click",async()=>{if(!A.hostAuthorized)return;A.drawPaused=true;A.drawRunning=false;clearTimeout(A.drawTimer);await writeLive({status:"paused",index:A.drawIndex,speed:A.drawSpeed});renderAfcl(["draw"])});document.getElementById("afclDrawSpeed")?.addEventListener("change",async e=>{A.drawSpeed=Number(e.target.value)||1;if(A.hostAuthorized)await writeLive({speed:A.drawSpeed,index:Number(A.live.index||0),status:A.live.status||"pending"})})}
async function runDraw(){clearTimeout(A.drawTimer);if(!A.drawRunning||A.drawPaused||!A.hostAuthorized)return;const total=A.draw.reveal.length;if(A.drawIndex>=total){A.drawRunning=false;await writeLive({status:"complete",index:total,speed:A.drawSpeed,completed_at:new Date().toISOString()});renderAfcl(["draw"]);return}A.drawIndex++;await writeLive({status:A.drawIndex>=total?"complete":"running",index:A.drawIndex,speed:A.drawSpeed});renderAfcl(["draw"]);if(A.drawIndex>=total){A.drawRunning=false;return}const checkpoint=A.drawIndex%192===0&&A.drawIndex<total,delay=(checkpoint?9000:3000)/A.drawSpeed;A.drawTimer=setTimeout(runDraw,delay)}
function groupSelector(){const i=Math.max(0,GROUP_LABELS.indexOf(A.selectedGroup)),prev=GROUP_LABELS[(i-1+GROUP_LABELS.length)%GROUP_LABELS.length],next=GROUP_LABELS[(i+1)%GROUP_LABELS.length];return `<div class="group-jump"><button id="afclGroupPrev" type="button" data-target="${prev}" aria-label="Previous group">‹</button><select id="afclGroupSelect" aria-label="Select AFCL group">${GROUP_LABELS.map(g=>`<option value="${g}" ${A.selectedGroup===g?"selected":""}>Group ${g}</option>`).join("")}</select><button id="afclGroupNext" type="button" data-target="${next}" aria-label="Next group">›</button></div>`}
function standingTable(rows,started){return `<div class="afcl-table-wrap"><table class="afcl-table afcl-standings-table"><caption class="sr-only">AFCL group standings</caption><thead><tr><th scope="col">#</th><th scope="col">Team / Manager</th><th scope="col">Chapter</th>${started?"<th scope=\"col\">P</th><th scope=\"col\">W</th><th scope=\"col\">D</th><th scope=\"col\">L</th><th scope=\"col\">PF</th><th scope=\"col\">PA</th><th scope=\"col\">GD</th><th scope=\"col\">PTS</th>":"<th scope=\"col\">Seed</th><th scope=\"col\">Pot</th>"}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${started&&i<4?"standing-qualify":""}"><td class="afcl-rank">${started?`#${r.pos}`:i+1}</td><td><a class="afcl-team" href="#/manager/${enc(r.id)}">${esc(r.team_name)}</a><span class="afcl-sub">${esc(r.manager_name)}</span></td><td>${esc(r.chapter)}</td>${started?`<td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.pf}</td><td>${r.pa}</td><td>${r.gd}</td><td><strong>${r.pts}</strong></td>`:`<td>#${r.seed}</td><td>P${r.pot}</td>`}</tr>`).join("")}</tbody></table></div>`}
function fixtureRoundMarkup(matches,gw){const current=currentGw();return `<div class="fixture-round"><h4>GAMEWEEK ${gw}</h4>${matches.map(m=>{const played=current>=gw,hs=played?Number((A.data.histories?.[m.home.id]||[])[gw-1]||0):null,as=played?Number((A.data.histories?.[m.away.id]||[])[gw-1]||0):null;return `<div class="fixture"><div class="home"><strong>${esc(m.home.team_name)}</strong><small>${esc(m.home.manager_name)} • ${esc(m.home.chapter)}</small></div><div class="score">${played?`${hs}–${as}`:"vs"}</div><div class="away"><strong>${esc(m.away.team_name)}</strong><small>${esc(m.away.manager_name)} • ${esc(m.away.chapter)}</small></div></div>`}).join("")}</div>`}
function fixtures(g){const rounds=fixtureRoundsForGroup(g),current=currentGw(),defaultGw=Math.min(AFCL.groupEndGw,Math.max(AFCL.groupStartGw,current<AFCL.groupStartGw?AFCL.groupStartGw:current));A.fixtureGw=Math.min(AFCL.groupEndGw,Math.max(AFCL.groupStartGw,Number(A.fixtureGw||defaultGw)));const selected=A.fixtureGw,idx=selected-AFCL.groupStartGw;const prev=Math.max(AFCL.groupStartGw,selected-1),next=Math.min(AFCL.groupEndGw,selected+1);const body=A.showAllFixtures?rounds.map((m,i)=>fixtureRoundMarkup(m,AFCL.groupStartGw+i)).join(""):fixtureRoundMarkup(rounds[idx]||[],selected);return `<section class="afcl-card"><div class="afcl-card-head"><div><h2>Group ${g.label} Fixtures</h2><p>${A.showAllFixtures?"All 23 rounds":`Gameweek ${selected} of 23 rounds`}</p></div></div><div class="fixture-toolbar"><button id="afclFixturePrev" type="button" data-gw="${prev}" ${selected===AFCL.groupStartGw?"disabled":""} aria-label="Previous fixture round">‹</button><select id="afclFixtureGw" aria-label="Select fixture Gameweek">${Array.from({length:23},(_,i)=>AFCL.groupStartGw+i).map(gw=>`<option value="${gw}" ${selected===gw?"selected":""}>GW${gw}</option>`).join("")}</select><button id="afclFixtureNext" type="button" data-gw="${next}" ${selected===AFCL.groupEndGw?"disabled":""} aria-label="Next fixture round">›</button></div><div class="fixture-all-toggle"><button id="afclFixtureAll" class="afcl-btn light" type="button">${A.showAllFixtures?"Show selected round":"Show all 23 rounds"}</button></div>${body}</section>`}
function groupsPage(){if(!drawComplete())return `${pageHead("AFCL Groups")}<section class="afcl-state-panel"><h2>Groups not drawn yet</h2><p>Official groups will be available after the AFCL Live Draw.</p></section>`;const g=A.draw.groups.find(x=>x.label===A.selectedGroup)||A.draw.groups[0],started=currentGw()>=AFCL.groupStartGw,rows=groupStandings(g);return `${pageHead("AFCL Group Stage","32 groups · 24 teams · Top 4 qualify")}${groupSelector()}<section class="afcl-card"><div class="afcl-card-head"><div><h2>Group ${g.label}</h2><p>${started?`Standings through GW${Math.min(currentGw(),25)}`:"Official draw roster · Group Stage starts GW3"}</p></div></div>${standingTable(rows,started)}</section>${fixtures(g)}`}
function knockoutPage(){const gw=currentGw();if(gw<26)return `${pageHead("AFCL Knockout")}<section class="afcl-state-panel"><h2>Knockout stage not active yet</h2><p>The Top 4 teams from each group qualify after GW25.</p></section>`;const st=knockoutStageState(gw);if(!st)return `${pageHead("AFCL Knockout")}<section class="afcl-state-panel"><h2>Knockout stage</h2><p>Official knockout information will appear here.</p></section>`;return `${pageHead("AFCL Knockout")}<div class="kpis afcl-knockout-stats"><div class="kpi home-summary-kpi"><span class="home-kpi-label">Current Round</span><div class="home-kpi-score"><strong>${esc(st.short)}</strong></div><div class="home-kpi-identity"><b>${esc(st.name)}</b></div></div><div class="kpi home-summary-kpi"><span class="home-kpi-label">Leg</span><div class="home-kpi-score"><strong>${st.leg}/${st.legs}</strong></div></div><div class="kpi home-summary-kpi"><span class="home-kpi-label">Teams Remaining</span><div class="home-kpi-score"><strong>${st.teams}</strong></div></div><div class="kpi home-summary-kpi"><span class="home-kpi-label">Gameweek</span><div class="home-kpi-score"><strong>GW${gw}</strong></div></div></div>`}
function rulesPage(){return `<div class="rules-clean-page"><div class="page-head"><div><h1>Rules & FAQ</h1></div></div><section class="rules-clean-section"><h2>ANSARA FPL</h2><div class="rules-panel"><details class="rule-block" open><summary>Individual Competition</summary><div class="rule-body"><ul><li>The Individual Competition runs from GW1 to GW38.</li><li>Rankings are based on each manager’s cumulative score.</li><li>The Gameweek score is the official FPL score after any transfer deductions.</li><li>The manager with the highest cumulative score after GW38 wins the competition.</li></ul></div></details><details class="rule-block"><summary>Chapter / Group Competition</summary><div class="rule-body"><ul><li>Only eligible ANSARA chapters compete in the Group Competition.</li><li>Each Gameweek, the five highest manager scores from an eligible chapter are counted.</li><li>Those five scores form the chapter’s Group GW Score for that Gameweek.</li><li>Group GW Scores are added throughout the season to form the chapter’s Cumulative Score.</li><li>The five contributing managers may change from one Gameweek to another.</li></ul></div></details></div></section><section class="rules-clean-section"><h2>ANSARA Fantasy Champions League</h2><div class="rules-panel"><details class="rule-block"><summary>Qualification & Seeding</summary><div class="rule-body"><p>GW2 is the official Qualification & Seeding round. The Top 768 managers qualify for AFCL and the remaining 35 are eliminated.</p><p><strong>Tie-break order:</strong> GW2 Score → Cumulative Score after GW2 → deterministic digital random draw.</p><p><strong>Seeding pots:</strong> Pot 1 Seeds 1–192, Pot 2 Seeds 193–384, Pot 3 Seeds 385–576 and Pot 4 Seeds 577–768.</p></div></details><details class="rule-block"><summary>Official Live Draw</summary><div class="rule-body"><ul><li>The 768 qualifiers are drawn into 32 groups from A to AF.</li><li>Each group contains 24 teams, with six teams from each seeding pot.</li><li>Same-chapter teams are separated as far as mathematically possible.</li><li>Only the authorised AFCL host can start, pause or resume the official Live Draw.</li><li>Public viewers follow the same synced draw position and cannot control the draw.</li><li>Group fixtures are published only after the full official draw has been completed.</li></ul></div></details><details class="rule-block"><summary>Group Stage</summary><div class="rule-body"><ul><li>The Group Stage runs from GW3 to GW25, with 23 Head-to-Head rounds for each team.</li><li>A win earns 3 AFCL Points, a draw earns 1 and a loss earns 0.</li><li>Each Head-to-Head result uses the manager’s net Gameweek score after transfer deductions.</li><li>The Top 4 teams in each group qualify for the Round of 128.</li></ul><p><strong>Group tie-break order:</strong> AFCL Points → Head-to-Head / mini-table → PF → Score Difference → GW2 Seed.</p></div></details><details class="rule-block"><summary>Knockout Stage</summary><div class="rule-body"><ul><li>Round of 128: GW26–27</li><li>Round of 64: GW28–29</li><li>Round of 32: GW30–31</li><li>Round of 16: GW32–33</li><li>Quarter Final: GW34–35</li><li>Semi Final: GW36–37</li><li>Grand Final: GW38</li></ul><p>Round of 128 pairings cannot match teams from the same AFCL group. Same-chapter pairings are avoided as far as possible.</p><p><strong>Aggregate tie-break order:</strong> Second-leg Score → Group Stage Finish → GW2 Seed.</p></div></details></div></section><section class="rules-clean-section rules-faq"><h2>Frequently Asked Questions</h2><div class="rules-panel"><details class="rule-block"><summary>Are transfer deductions included in the Gameweek score?</summary><div class="rule-body"><p>Yes. Where applicable, competition scores use the net Gameweek score after transfer deductions.</p></div></details><details class="rule-block"><summary>How is the Chapter Group Competition score calculated?</summary><div class="rule-body"><p>The five highest net Gameweek scores from each eligible chapter are counted every Gameweek. Their total is the Group GW Score, and all Group GW Scores are added to form the chapter’s Cumulative Score.</p></div></details><details class="rule-block"><summary>How do managers qualify for AFCL?</summary><div class="rule-body"><p>The Top 768 managers after the official GW2 Qualification & Seeding round qualify for AFCL. The remaining 35 are eliminated.</p></div></details><details class="rule-block"><summary>When will AFCL groups and fixtures be published?</summary><div class="rule-body"><p>Groups are revealed through the official AFCL Live Draw. Fixtures become available only after the full draw has been completed.</p></div></details><details class="rule-block"><summary>Who can control the AFCL Live Draw?</summary><div class="rule-body"><p>Only the authorised AFCL host can start, pause or resume the official Live Draw. Public viewers cannot control it.</p></div></details><details class="rule-block"><summary>How are ties decided in AFCL?</summary><div class="rule-body"><p>The tie-break order depends on the competition stage. Qualification, Group Stage and Knockout Stage each follow the official tie-break order stated in the relevant rules section above.</p></div></details></div></section></div>`}
function managerPage(id){const r=A.seedMap.get(String(id));if(!r)return '<div class="empty">Manager not found.</div>';const gl=drawComplete()?A.draw.byId.get(String(r.id)):null,g=gl?A.draw.groups.find(x=>x.label===gl):null,record=g?groupStandings(g).find(x=>String(x.id)===String(r.id)):null;return `${pageHead(r.team_name,`${r.manager_name} • ${r.chapter}`)}<section class="afcl-card"><div class="afcl-card-head"><div><h2>AFCL 2026/27</h2><p>Official competition record</p></div><span class="afcl-badge ${r.qualified?"q":"out"}">${r.qualified?"QUALIFIED":"DID NOT QUALIFY"}</span></div><div class="afcl-kpis" style="padding:0 13px 13px"><div class="afcl-kpi"><span>GW2 Seed</span><strong>#${r.seed}</strong><small>${nfmt(r.gw2)} score</small></div><div class="afcl-kpi"><span>Pot</span><strong>${r.pot?`P${r.pot}`:"—"}</strong><small>${r.qualified?"Top 768":"Eliminated"}</small></div><div class="afcl-kpi"><span>Group</span><strong>${gl||"—"}</strong><small>${gl?"Official draw":"Not published"}</small></div><div class="afcl-kpi"><span>AFCL Pts</span><strong>${record?.pts??"—"}</strong><small>${record?`P${record.p} W${record.w} D${record.d} L${record.l}`:"Group Stage not active"}</small></div></div></section>${g?`<section class="afcl-card"><div class="afcl-card-head"><div><h2>Group ${g.label}</h2><p>Current AFCL standing</p></div><a class="afcl-btn light" href="${ah("groups")}">View group</a></div>${standingTable(groupStandings(g),currentGw()>=3)}</section>`:""}<a class="afcl-btn light" href="#/manager/${enc(r.id)}">Back to full ANSARA FPL profile</a>`}

function bindAfclEvents(){document.getElementById("afclQualSearch")?.addEventListener("input",async e=>{const v=e.target.value;A.search=v;A.qualLimit=120;await renderAfcl(["qualification"],false);const n=document.getElementById("afclQualSearch");if(n){n.focus();try{n.setSelectionRange(v.length,v.length)}catch{}}});document.getElementById("afclQualFilter")?.addEventListener("change",e=>{A.filter=e.target.value;A.qualLimit=120;renderAfcl(["qualification"],false)});document.getElementById("afclQualMore")?.addEventListener("click",()=>{A.qualLimit+=120;renderAfcl(["qualification"],false)});document.querySelectorAll("[data-afcl-pot]").forEach(b=>b.addEventListener("click",()=>{A.selectedPot=Number(b.dataset.afclPot)||1;A.potSearch="";renderAfcl(["pots"],false)}));document.getElementById("afclPotSearch")?.addEventListener("input",async e=>{const v=e.target.value;A.potSearch=v;await renderAfcl(["pots"],false);const n=document.getElementById("afclPotSearch");if(n){n.focus();try{n.setSelectionRange(v.length,v.length)}catch{}}});document.getElementById("afclGroupSelect")?.addEventListener("change",e=>{A.selectedGroup=e.target.value;renderAfcl(["groups"],false)});document.getElementById("afclGroupPrev")?.addEventListener("click",e=>{A.selectedGroup=e.currentTarget.dataset.target;renderAfcl(["groups"],false)});document.getElementById("afclGroupNext")?.addEventListener("click",e=>{A.selectedGroup=e.currentTarget.dataset.target;renderAfcl(["groups"],false)});document.getElementById("afclFixtureGw")?.addEventListener("change",e=>{A.fixtureGw=Number(e.target.value);A.showAllFixtures=false;renderAfcl(["groups"],false)});document.getElementById("afclFixturePrev")?.addEventListener("click",e=>{A.fixtureGw=Number(e.currentTarget.dataset.gw);A.showAllFixtures=false;renderAfcl(["groups"],false)});document.getElementById("afclFixtureNext")?.addEventListener("click",e=>{A.fixtureGw=Number(e.currentTarget.dataset.gw);A.showAllFixtures=false;renderAfcl(["groups"],false)});document.getElementById("afclFixtureAll")?.addEventListener("click",()=>{A.showAllFixtures=!A.showAllFixtures;renderAfcl(["groups"],false)});document.getElementById("afclDrawGroupSelect")?.addEventListener("change",e=>{A.drawBoardGroup=e.target.value;renderAfcl(["draw"],false)});document.querySelectorAll("[data-afcl-draw-group]").forEach(b=>b.addEventListener("click",()=>{A.drawBoardGroup=b.dataset.afclDrawGroup;renderAfcl(["draw"],false)}));bindDraw()}
async function renderAfcl(route=afclRoute(),scroll=true){if(!route)return;if(route[0]==="manager"){location.hash=`#/manager/${route[1]||""}`;return}const appEl=document.getElementById("app");if(!appEl||A.rendering)return;A.rendering=true;try{ensureAfclNav();await loadAfcl();const p=route[0]||"overview";let body;if(p==="overview")body=overviewPage();else if(p==="qualification")body=qualificationPage();else if(p==="pots")body=potsPage();else if(p==="draw")body=drawPage();else if(p==="groups")body=groupsPage();else if(p==="knockout")body=knockoutPage();else body=overviewPage();appEl.innerHTML=`<div id="afclNativeRoot" data-afcl-root="1" data-afcl-page="${esc(p)}">${tabs(p)}${body}</div>`;applyProductRoute(["afcl",p]);bindAfclEvents();if(scroll)window.scrollTo(0,0)}catch(e){console.error(e);appEl.innerHTML='<div id="afclNativeRoot" data-afcl-root="1" class="empty">Unable to load AFCL. Please refresh.</div>'}finally{A.rendering=false}}
async function renderRules(scroll=true){const appEl=document.getElementById("app");if(!appEl||A.rendering)return;A.rendering=true;try{ensureRulesNav();appEl.innerHTML=`<div id="rulesNativeRoot" data-rules-root="1">${rulesPage()}</div>`;applyProductRoute(["rules"]);if(scroll)window.scrollTo(0,0)}finally{A.rendering=false}}
async function enhanceMainRoutes(){ensureAfclNav();const r=(location.hash||"").replace(/^#\/?/,"").split("/").filter(Boolean),route=r[0]||"home",appEl=document.getElementById("app");if(!appEl)return;if(route==="manager"){await loadAfcl().catch(()=>null);const m=A.seedMap.get(String(decodeURIComponent(r[1]||"")));if(m&&!document.getElementById("afclManagerCard")){const gl=drawComplete()?A.draw?.byId?.get(String(m.id)):null,g=gl?A.draw.groups.find(x=>x.label===gl):null,rec=g?groupStandings(g).find(x=>String(x.id)===String(m.id)):null;const s=document.createElement("section");s.id="afclManagerCard";s.className="section afcl-profile-integration";s.innerHTML=`<div class="section-head"><div><h2>ANSARA Fantasy Champions League</h2><span class="subline">Competition record</span></div></div><div class="profile-kpis" style="padding:0 14px 14px"><div><span>AFCL Status</span><strong style="font-size:15px;color:${m.qualified?"#198754":"#b3261e"}">${m.qualified?"Qualified":"Did Not Qualify"}</strong></div><div><span>GW2 Seed</span><strong>#${m.seed}</strong></div><div><span>Pot / Group</span><strong>${m.pot?`P${m.pot}`:"—"}${gl?` • ${gl}`:""}</strong></div><div><span>AFCL Points</span><strong>${rec?.pts??"—"}</strong></div></div>`;appEl.appendChild(s)}}if(route==="more"&&!document.getElementById("afclRulesMoreCard")){const grid=appEl.querySelector(".more-grid");if(grid){const a=document.createElement("a");a.id="afclRulesMoreCard";a.href="#/rules";a.className="more-card";a.innerHTML="<span></span>Rules & FAQ";grid.appendChild(a)}}applyProductRoute(r);if(route==="more")enhanceMoreVisuals(appEl)}
let afclRouteTimer=null;
function routeSync(){const r=afclRoute(),appEl=document.getElementById("app");if(!appEl)return;if(r?.[0]==="rules"){location.hash="#/rules";return}if(r?.[0]==="manager"){location.hash=`#/manager/${r[1]||""}`;return}if(r){const root=appEl.querySelector("[data-afcl-root]");const target=r[0]||"overview";if(root&&root.dataset.afclPage===target){ensureAfclNav();applyProductRoute(["afcl",target]);return}renderAfcl(r);return}if(rulesRoute()){if(appEl.querySelector("[data-rules-root]")){ensureRulesNav();applyProductRoute(["rules"]);return}renderRules();return}enhanceMainRoutes()}
const observer=new MutationObserver(()=>{if(A.rendering)return;const r=afclRoute(),appEl=document.getElementById("app");if(!appEl)return;clearTimeout(afclRouteTimer);if(r?.[0]==="rules"){afclRouteTimer=setTimeout(()=>{location.hash="#/rules"},0)}else if(r){if(!appEl.querySelector("[data-afcl-root]"))afclRouteTimer=setTimeout(()=>renderAfcl(r),0)}else if(rulesRoute()){if(!appEl.querySelector("[data-rules-root]"))afclRouteTimer=setTimeout(()=>renderRules(),0)}else afclRouteTimer=setTimeout(enhanceMainRoutes,0)});const appEl=document.getElementById("app");if(appEl)observer.observe(appEl,{childList:true});window.addEventListener("hashchange",()=>{clearTimeout(afclRouteTimer);afclRouteTimer=setTimeout(routeSync,0)});

/* Hard-safe exit from AFCL. The core dashboard and AFCL are two routers sharing
   one hash space. When leaving AFCL, perform one clean reload into the selected
   core route so stale AFCL rendering can never capture the navigation state. */
document.addEventListener("click",e=>{
  if(!afclRoute()&&!rulesRoute())return;
  const link=e.target.closest?.(".bottom-nav a");
  if(!link||link.matches("[data-afcl-main]"))return;
  const href=link.getAttribute("href")||"";
  if(!href.startsWith("#/"))return;
  e.preventDefault();
  e.stopImmediatePropagation();
  history.replaceState(null,"",`${location.pathname}${location.search}${href}`);
  location.reload();
},true);

ensureProductUI();ensureApprovedPolish();ensureAfclNav();routeSync();

onValue(afclLiveRef,s=>{A.live={status:"pending",index:0,speed:1,...(s.val()||{})};A.drawIndex=Number(A.live.index||0);A.drawSpeed=Number(A.live.speed||1);A.liveReady=true;if(afclRoute())renderAfcl(afclRoute(),false);else if(rulesRoute())ensureRulesNav();else enhanceMainRoutes()},e=>{A.liveReady=true;console.warn("AFCL live sync",e)});
onAuthStateChanged(auth,user=>{if(user)startRealtimeAudience(user)});
signInAnonymously(auth).catch(e=>{console.error("Anonymous sign-in failed",e);audienceUnavailable()});
